        targetLifeSec: 1.0,
        targetLifeStartSec: 1.05,
        targetLifeEndSec: 0.52,
        targetBaseX: 0,
        targetBaseY: 0,
        targetStartSize: 74,
        targetEndSize: 40,
        timerLabel: timerLabel,
        hitLabel: hitLabel,
        missLabel: missLabel,
        accLabel: accLabel,
        statusLabel: statusLabel,
        targetBtn: targetBtn,
