    var defaultIndex = GetRuntimeButtonGroupDefaultIndex(key, meta.defaultIndex);
    if (defaultIndex >= meta.options.length) defaultIndex = 0;
    return ApplyRuntimeButtonGroupIndex(key, defaultIndex, runCommand);
